121	/* Check a file name for permission by stringmatch on one of the */
122	/* strings of the permitgroup array. */
123	static int
124	check_file_permissions_reduced(i_ctx_t *i_ctx_p, const char *fname, int len,
125	                        gx_io_device *iodev, const char *permitgroup)
126	{
127	    long i;
128	    ref *permitlist = NULL;
129	    /* an empty string (first character == 0) if '\' character is */
130	    /* recognized as a file name separator as on DOS & Windows    */
131	    const char *win_sep2 = "\\";
132	    bool use_windows_pathsep = (gs_file_name_check_separator(win_sep2, 1, win_sep2) == 1);
133	    uint plen = gp_file_name_parents(fname, len);
134	
135	    /* we're protecting arbitrary file system accesses, not Postscript device accesses.
136	     * Although, note that %pipe% is explicitly checked for and disallowed elsewhere
137	     */
138	    if (iodev && iodev != iodev_default(imemory)) {
139	        return 0;
140	    }
141	
142	    /* Assuming a reduced file name. */
143	    if (dict_find_string(&(i_ctx_p->userparams), permitgroup, &permitlist) <= 0)
144	        return 0;       /* if Permissions not found, just allow access */
145	
146	    for (i=0; i<r_size(permitlist); i++) {
147	        ref permitstring;
148	        const string_match_params win_filename_params = {
149	                '*', '?', '\\', true, true      /* ignore case & '/' == '\\' */
150	        };
151	        const byte *permstr;
152	        uint permlen;
153	        int cwd_len = 0;
154	
155	        if (array_get(imemory, permitlist, i, &permitstring) < 0 ||
156	            r_type(&permitstring) != t_string
157	           )
158	            break;      /* any problem, just fail */
159	        permstr = permitstring.value.bytes;
160	        permlen = r_size(&permitstring);
161	        /*
162	         * Check if any file name is permitted with "*".
163	         */
164	        if (permlen == 1 && permstr[0] == '*')
165	            return 0;           /* success */
166	        /*
167	         * If the filename starts with parent references,
168	         * the permission element must start with same number of parent references.
169	         */
170	        if (plen != 0 && plen != gp_file_name_parents((const char *)permstr, permlen))
171	            continue;
172	        cwd_len = gp_file_name_cwds((const char *)permstr, permlen);
173	        /*
174	         * If the permission starts with "./", absolute paths
175	         * are not permitted.
176	         */
177	        if (cwd_len > 0 && gp_file_name_is_absolute(fname, len))
178	            continue;
179	        /*
180	         * If the permission starts with "./", relative paths
181	         * with no "./" are allowed as well as with "./".
182	         * 'fname' has no "./" because it is reduced.
183	         */
184	        if (string_match( (const unsigned char*) fname, len,
185	                          permstr + cwd_len, permlen - cwd_len,
186	                use_windows_pathsep ? &win_filename_params : NULL))
187	            return 0;           /* success */
188	    }
189	    /* not found */
190	    return gs_error_invalidfileaccess;
191	}
