193	/* Check a file name for permission by stringmatch on one of the */
194	/* strings of the permitgroup array */
195	static int
196	check_file_permissions(i_ctx_t *i_ctx_p, const char *fname, int len,
197	                        gx_io_device *iodev, const char *permitgroup)
198	{
199	    char fname_reduced[gp_file_name_sizeof];
200	    uint rlen = sizeof(fname_reduced);
201	
202	    if (gp_file_name_reduce(fname, len, fname_reduced, &rlen) != gp_combine_success)
203	        return gs_error_invalidaccess;         /* fail if we couldn't reduce */
204	    return check_file_permissions_reduced(i_ctx_p, fname_reduced, rlen, iodev, permitgroup);
205	}
