207	/* z_check_file_permissions: see zfile.h for explanation
208	 */
209	int
210	z_check_file_permissions(gs_memory_t *mem, const char *fname, const int len, const char *permission)
211	{
212	    i_ctx_t *i_ctx_p = get_minst_from_memory(mem)->i_ctx_p;
213	    gs_parsed_file_name_t pname;
214	    const char *permitgroup = permission[0] == 'r' ? "PermitFileReading" : "PermitFileWriting";
215	    int code = gs_parse_file_name(&pname, fname, len, imemory);
216	    if (code < 0)
217	        return code;
218	
219	    if (pname.iodev && i_ctx_p->LockFilePermissions
220	         && strcmp(pname.iodev->dname, "%pipe%") == 0) {
221	        code = gs_note_error(gs_error_invalidfileaccess);
222	    }
223	    else {
224	        code = check_file_permissions(i_ctx_p, pname.fname, pname.len, pname.iodev, permitgroup);
225	    }
226	    return code;
227	}
