229	/* <name_string> <access_string> file <file> */
230	int                             /* exported for zsysvm.c */
231	zfile(i_ctx_t *i_ctx_p)
232	{
233	    os_ptr op = osp;
234	    char file_access[4];
235	    gs_parsed_file_name_t pname;
236	    int code = parse_file_access_string(op, file_access);
237	    stream *s;
238	
239	    if (code < 0)
240	        return code;
241	    code = parse_file_name(op-1, &pname, i_ctx_p->LockFilePermissions, imemory);
242	    if (code < 0)
243	        return code;
244	        /*
245	         * HACK: temporarily patch the current context pointer into the
246	         * state pointer for stdio-related devices.  See ziodev.c for
247	         * more information.
248	         */
249	    if (pname.iodev && pname.iodev->dtype == iodev_dtype_stdio) {
250	        bool statement = (strcmp(pname.iodev->dname, "%statementedit%") == 0);
251	        bool lineedit = (strcmp(pname.iodev->dname, "%lineedit%") == 0);
252	        if (pname.fname)
253	            return_error(gs_error_invalidfileaccess);
254	        if (statement || lineedit) {
255	            /* These need special code to support callouts */
256	            gx_io_device *indev = gs_findiodevice(imemory,
257	                                                  (const byte *)"%stdin", 6);
258	            stream *ins;
259	            if (strcmp(file_access, "r"))
260	                return_error(gs_error_invalidfileaccess);
261	            indev->state = i_ctx_p;
262	            code = (indev->procs.open_device)(indev, file_access, &ins, imemory);
263	            indev->state = 0;
264	            if (code < 0)
265	                return code;
266	            check_ostack(2);
267	            push(2);
268	            make_stream_file(op - 3, ins, file_access);
269	            make_bool(op-2, statement);
270	            make_int(op-1, 0);
271	            make_string(op, icurrent_space, 0, NULL);
272	            return zfilelineedit(i_ctx_p);
273	        }
274	        pname.iodev->state = i_ctx_p;
275	        code = (*pname.iodev->procs.open_device)(pname.iodev,
276	                                                 file_access, &s, imemory);
277	        pname.iodev->state = NULL;
278	    } else {
279	        if (pname.iodev == NULL)
280	            pname.iodev = iodev_default(imemory);
281	        code = zopen_file(i_ctx_p, &pname, file_access, &s, imemory);
282	    }
283	    if (code < 0)
284	        return code;
285	    code = ssetfilename(s, op[-1].value.const_bytes, r_size(op - 1));
286	    if (code < 0) {
287	        sclose(s);
288	        return_error(gs_error_VMerror);
289	    }
290	    make_stream_file(op - 1, s, file_access);
291	    pop(1);
292	    return code;
293	}
