295	/*
296	 * Files created with .tempfile permit some operations even if the
297	 * temp directory is not explicitly named on the PermitFile... path
298	 * The names 'SAFETY' and 'tempfiles' are defined by gs_init.ps
299	*/
300	static bool
301	file_is_tempfile(i_ctx_t *i_ctx_p, const uchar *fname, int len)
302	{
303	    ref *SAFETY;
304	    ref *tempfiles;
305	    ref kname;
306	
307	    if (dict_find_string(systemdict, "SAFETY", &SAFETY) <= 0 ||
308	            dict_find_string(SAFETY, "tempfiles", &tempfiles) <= 0)
309	        return false;
310	    if (name_ref(imemory, fname, len, &kname, -1) < 0 ||
311	            dict_find(tempfiles, &kname, &SAFETY) <= 0)
312	        return false;
313	    return true;
314	}
315	
316	static int
317	record_file_is_tempfile(i_ctx_t *i_ctx_p, const uchar *fname, int len, bool add)
318	{
319	    ref *SAFETY;
320	    ref *tempfiles;
321	    ref kname, bref;
322	    int code = 0;
323	
324	    if (dict_find_string(systemdict, "SAFETY", &SAFETY) <= 0 ||
325	            dict_find_string(SAFETY, "tempfiles", &tempfiles) <= 0) {
326	        return 0;
327	    }
328	    if ((code = name_ref(imemory, fname, len, &kname, 1)) < 0) {
329	        return code;
330	    }
331	    make_bool(&bref, true);
332	    if (add)
333	        return idict_put(tempfiles, &kname, &bref);
334	    else
335	        return idict_undef(tempfiles, &kname);
336	}
