340	/* <string> deletefile - */
341	static int
342	zdeletefile(i_ctx_t *i_ctx_p)
343	{
344	    os_ptr op = osp;
345	    gs_parsed_file_name_t pname;
346	    int code = parse_real_file_name(op, &pname, imemory, "deletefile");
347	    bool is_temp = false;
348	
349	    if (code < 0)
350	        return code;
351	    if (pname.iodev == iodev_default(imemory)) {
352	        if ((code = check_file_permissions(i_ctx_p, pname.fname, pname.len,
353	                pname.iodev, "PermitFileControl")) < 0 &&
354	                 !(is_temp = file_is_tempfile(i_ctx_p, op->value.bytes, r_size(op)))) {
355	            return code;
356	        }
357	    }
358	    code = (*pname.iodev->procs.delete_file)(pname.iodev, pname.fname);
359	
360	    if (code >= 0 && is_temp)
361	        code = record_file_is_tempfile(i_ctx_p, (unsigned char *)pname.fname, strlen(pname.fname), false);
362	
363	    gs_free_file_name(&pname, "deletefile");
364	    if (code < 0)
365	        return code;
366	    pop(1);
367	    return 0;
368	}
