370	/* <template> <proc> <scratch> filenameforall - */
371	static int file_continue(i_ctx_t *);
372	static int file_cleanup(i_ctx_t *);
373	static int
374	zfilenameforall(i_ctx_t *i_ctx_p)
375	{
376	    os_ptr op = osp;
377	    file_enum *pfen;
378	    gx_io_device *iodev = NULL;
379	    gs_parsed_file_name_t pname;
380	    int code = 0;
381	
382	    check_write_type(*op, t_string);
383	    check_proc(op[-1]);
384	    check_read_type(op[-2], t_string);
385	    /* Push a mark, the iodev, devicenamelen, the scratch string, the enumerator, */
386	    /* and the procedure, and invoke the continuation. */
387	    check_estack(7);
388	    /* Get the iodevice */
389	    code = parse_file_name(op-2, &pname, i_ctx_p->LockFilePermissions, imemory);
390	    if (code < 0)
391	        return code;
392	    iodev = (pname.iodev == NULL) ? iodev_default(imemory) : pname.iodev;
393	
394	    /* Check for several conditions that just cause us to return success */
395	    if (pname.len == 0 || iodev->procs.enumerate_files == iodev_no_enumerate_files) {
396	        pop(3);
397	        return 0;       /* no pattern, or device not found -- just return */
398	    }
399	    pfen = iodev->procs.enumerate_files(imemory, iodev, (const char *)pname.fname,
400	                pname.len);
401	    if (pfen == 0)
402	        return_error(gs_error_VMerror);
403	    push_mark_estack(es_for, file_cleanup);
404	    ++esp;
405	    make_istruct(esp, 0, iodev);
406	    ++esp;
407	    make_int(esp, r_size(op-2) - pname.len);
408	    *++esp = *op;
409	    ++esp;
410	    make_istruct(esp, 0, pfen);
411	    *++esp = op[-1];
412	    pop(3);
413	    code = file_continue(i_ctx_p);
414	    return (code == o_pop_estack ? o_push_estack : code);
415	}
416	/* Continuation operator for enumerating files */
417	static int
418	file_continue(i_ctx_t *i_ctx_p)
419	{
420	    os_ptr op = osp;
421	    es_ptr pscratch = esp - 2;
422	    file_enum *pfen = r_ptr(esp - 1, file_enum);
423	    int devlen = esp[-3].value.intval;
424	    gx_io_device *iodev = r_ptr(esp - 4, gx_io_device);
425	    uint len = r_size(pscratch);
426	    uint code;
427	
428	    if (len < devlen) {
429	        esp -= 5;               /* pop proc, pfen, devlen, iodev , mark */
430	        return_error(gs_error_rangecheck);     /* not even room for device len */
431	    }
432	
433	    do {
434	        memcpy((char *)pscratch->value.bytes, iodev->dname, devlen);
435	        code = iodev->procs.enumerate_next(imemory, pfen, (char *)pscratch->value.bytes + devlen,
436	                    len - devlen);
437	        if (code == ~(uint) 0) {    /* all done */
438	            esp -= 5;               /* pop proc, pfen, devlen, iodev , mark */
439	            return o_pop_estack;
440	        } else if (code > len) {      /* overran string */
441	            return_error(gs_error_rangecheck);
442	        }
443	        else if (iodev != iodev_default(imemory)
444	              || (check_file_permissions(i_ctx_p, (char *)pscratch->value.bytes, code + devlen, iodev, "PermitFileReading")) == 0) {
445	            push(1);
446	            ref_assign(op, pscratch);
447	            r_set_size(op, code + devlen);
448	            push_op_estack(file_continue);  /* come again */
449	            *++esp = pscratch[2];   /* proc */
450	            return o_push_estack;
451	        }
452	    } while(1);
453	}
454	/* Cleanup procedure for enumerating files */
455	static int
456	file_cleanup(i_ctx_t *i_ctx_p)
457	{
458	    gx_io_device *iodev = r_ptr(esp + 2, gx_io_device);
459	
460	    iodev->procs.enumerate_close(imemory, r_ptr(esp + 5, file_enum));
461	    return 0;
462	}
