464	/* <string1> <string2> renamefile - */
465	static int
466	zrenamefile(i_ctx_t *i_ctx_p)
467	{
468	    int code;
469	    os_ptr op = osp;
470	    gs_parsed_file_name_t pname1, pname2;
471	
472	    code = parse_real_file_name(op, &pname2, imemory, "renamefile(to)");
473	    if (code < 0)
474	        return code;
475	
476	    pname1.fname = 0;
477	    code = parse_real_file_name(op - 1, &pname1, imemory, "renamefile(from)");
478	    if (code >= 0) {
479	        gx_io_device *iodev_dflt = iodev_default(imemory);
480	        if (pname1.iodev != pname2.iodev ) {
481	            if (pname1.iodev == iodev_dflt)
482	                pname1.iodev = pname2.iodev;
483	            if (pname2.iodev == iodev_dflt)
484	                pname2.iodev = pname1.iodev;
485	        }
486	        if (pname1.iodev != pname2.iodev ||
487	            (pname1.iodev == iodev_dflt &&
488	                /*
489	                 * We require FileControl permissions on the source path
490	                 * unless it is a temporary file. Also, we require FileControl
491	                 * and FileWriting permissions to the destination file/path.
492	                 */
493	              ((check_file_permissions(i_ctx_p, pname1.fname, pname1.len,
494	                                        pname1.iodev, "PermitFileControl") < 0 &&
495	                  !file_is_tempfile(i_ctx_p, op[-1].value.bytes, r_size(op - 1))) ||
496	              (check_file_permissions(i_ctx_p, pname2.fname, pname2.len,
497	                                        pname2.iodev, "PermitFileControl") < 0 ||
498	              check_file_permissions(i_ctx_p, pname2.fname, pname2.len,
499	                                        pname2.iodev, "PermitFileWriting") < 0 )))) {
500	            code = gs_note_error(gs_error_invalidfileaccess);
501	        } else {
502	            code = (*pname1.iodev->procs.rename_file)(pname1.iodev,
503	                            pname1.fname, pname2.fname);
504	        }
505	    }
506	    gs_free_file_name(&pname2, "renamefile(to)");
507	    gs_free_file_name(&pname1, "renamefile(from)");
508	    if (code < 0)
509	        return code;
510	    pop(2);
511	    return 0;
512	}
