514	/* <file> status <open_bool> */
515	/* <string> status <pages> <bytes> <ref_time> <creation_time> true */
516	/* <string> status false */
517	static int
518	zstatus(i_ctx_t *i_ctx_p)
519	{
520	    os_ptr op = osp;
521	
522	    switch (r_type(op)) {
523	        case t_file:
524	            {
525	                stream *s;
526	
527	                make_bool(op, (file_is_valid(s, op) ? 1 : 0));
528	            }
529	            return 0;
530	        case t_string:
531	            {
532	                gs_parsed_file_name_t pname;
533	                struct stat fstat;
534	                int code = parse_file_name(op, &pname,
535	                                           i_ctx_p->LockFilePermissions, imemory);
536	                if (code < 0) {
537	                    if (code == gs_error_undefinedfilename) {
538	                        make_bool(op, 0);
539	                        code = 0;
540	                    }
541	                    return code;
542	                }
543	                code = gs_terminate_file_name(&pname, imemory, "status");
544	                if (code < 0)
545	                    return code;
546	                if ((code = check_file_permissions(i_ctx_p, pname.fname, pname.len,
547	                                       pname.iodev, "PermitFileReading")) >= 0) {
548	                    code = (*pname.iodev->procs.file_status)(pname.iodev,
549	                                                       pname.fname, &fstat);
550	                }
551	                switch (code) {
552	                    case 0:
553	                        check_ostack(4);
554	                        /*
555	                         * Check to make sure that the file size fits into
556	                         * a PostScript integer.  (On some systems, long is
557	                         * 32 bits, but file sizes are 64 bits.)
558	                         */
559	                        push(4);
560	                        make_int(op - 4, stat_blocks(&fstat));
561	                        make_int(op - 3, fstat.st_size);
562	                        /*
563	                         * We can't check the value simply by using ==,
564	                         * because signed/unsigned == does the wrong thing.
565	                         * Instead, since integer assignment only keeps the
566	                         * bottom bits, we convert the values to double
567	                         * and then test for equality.  This handles all
568	                         * cases of signed/unsigned or width mismatch.
569	                         */
570	                        if ((double)op[-4].value.intval !=
571	                              (double)stat_blocks(&fstat) ||
572	                            (double)op[-3].value.intval !=
573	                              (double)fstat.st_size
574	                            )
575	                            return_error(gs_error_limitcheck);
576	                        make_int(op - 2, fstat.st_mtime);
577	                        make_int(op - 1, fstat.st_ctime);
578	                        make_bool(op, 1);
579	                        break;
580	                    case gs_error_undefinedfilename:
581	                        make_bool(op, 0);
582	                        code = 0;
583	                }
584	                gs_free_file_name(&pname, "status");
585	                return code;
586	            }
587	        default:
588	            return_op_typecheck(op);
589	    }
590	}
