710	/* A "simple" prefix is defined as a (possibly empty) string of
711	   alphanumeric, underscore, and hyphen characters. */
712	static bool
713	prefix_is_simple(const char *pstr)
714	{
715	    int i;
716	    char c;
717	
718	    for (i = 0; (c = pstr[i]) != 0; i++) {
719	        if (!(c == '-' || c == '_' || (c >= '0' && c <= '9') ||
720	              (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z')))
721	            return false;
722	    }
723	    return true;
724	}
