726	/* <prefix|null> <access_string> .tempfile <name_string> <file> */
727	static int
728	ztempfile(i_ctx_t *i_ctx_p)
729	{
730	    os_ptr op = osp;
731	    const char *pstr;
732	    char fmode[4];
733	    int code = parse_file_access_string(op, fmode);
734	    char *prefix = NULL;
735	    char *fname= NULL;
736	    uint fnlen;
737	    gp_file *sfile;
738	    stream *s;
739	    byte *buf, *sbody;
740	
741	    if (code < 0)
742	        return code;
743	    prefix = (char *)gs_alloc_bytes(imemory, gp_file_name_sizeof, "ztempfile(prefix)");
744	    fname = (char *)gs_alloc_bytes(imemory, gp_file_name_sizeof, "ztempfile(fname)");
745	    if (!prefix || !fname) {
746	        code = gs_note_error(gs_error_VMerror);
747	        goto done;
748	    }
749	
750	    strcat(fmode, gp_fmode_binary_suffix);
751	    if (r_has_type(op - 1, t_null))
752	        pstr = gp_scratch_file_name_prefix;
753	    else {
754	        uint psize;
755	
756	        check_read_type(op[-1], t_string);
757	        psize = r_size(op - 1);
758	        if (psize >= gp_file_name_sizeof) {
759	            code = gs_note_error(gs_error_rangecheck);
760	            goto done;
761	        }
762	        memcpy(prefix, op[-1].value.const_bytes, psize);
763	        prefix[psize] = 0;
764	        pstr = prefix;
765	    }
766	
767	    if (gp_file_name_is_absolute(pstr, strlen(pstr))) {
768	        int plen = strlen(pstr);
769	        const char *sep = gp_file_name_separator();
770	#ifdef DEBUG
771	        int seplen = strlen(sep);
772	        if (seplen != 1)
773	            return_error(gs_error_Fatal);
774	#endif
775	        /* strip off the file name prefix, leave just the directory name
776	         * so we can check if we are allowed to write to it
777	         */
778	        for ( ; plen >=0; plen--) {
779	            if (pstr[plen] == sep[0])
780	                break;
781	        }
782	        memcpy(fname, pstr, plen);
783	        fname[plen] = '\0';
784	        if (check_file_permissions(i_ctx_p, fname, strlen(fname),
785	                                   NULL, "PermitFileWriting") < 0) {
786	            code = gs_note_error(gs_error_invalidfileaccess);
787	            goto done;
788	        }
789	    } else if (!prefix_is_simple(pstr)) {
790	        code = gs_note_error(gs_error_invalidfileaccess);
791	        goto done;
792	    }
793	
794	    s = file_alloc_stream(imemory, "ztempfile(stream)");
795	    if (s == 0) {
796	        code = gs_note_error(gs_error_VMerror);
797	        goto done;
798	    }
799	    buf = gs_alloc_bytes(imemory, file_default_buffer_size,
800	                         "ztempfile(buffer)");
801	    if (buf == 0) {
802	        code = gs_note_error(gs_error_VMerror);
803	        goto done;
804	    }
805	    sfile = gp_open_scratch_file(imemory, pstr, fname, fmode);
806	    if (sfile == 0) {
807	        gs_free_object(imemory, buf, "ztempfile(buffer)");
808	        code = gs_note_error(gs_error_invalidfileaccess);
809	        goto done;
810	    }
811	    fnlen = strlen(fname);
812	    sbody = ialloc_string(fnlen, ".tempfile(fname)");
813	    if (sbody == 0) {
814	        gs_free_object(imemory, buf, "ztempfile(buffer)");
815	        code = gs_note_error(gs_error_VMerror);
816	        goto done;
817	    }
818	    memcpy(sbody, fname, fnlen);
819	    file_init_stream(s, sfile, fmode, buf, file_default_buffer_size);
820	    code = ssetfilename(s, (const unsigned char*) fname, fnlen);
821	    if (code < 0) {
822	        gx_io_device *iodev_dflt = iodev_default(imemory);
823	        sclose(s);
824	        iodev_dflt->procs.delete_file(iodev_dflt, fname);
825	        ifree_string(sbody, fnlen, ".tempfile(fname)");
826	        code = gs_note_error(gs_error_VMerror);
827	        goto done;
828	    }
829	    make_string(op - 1, a_readonly | icurrent_space, fnlen, sbody);
830	    make_stream_file(op, s, fmode);
831	    code = record_file_is_tempfile(i_ctx_p, (unsigned char *)fname, fnlen, true);
832	
833	done:
834	    if (prefix)
835	        gs_free_object(imemory, prefix, "ztempfile(prefix)");
836	    if (fname)
837	        gs_free_object(imemory, fname, "ztempfile(fname)");
838	    return code;
839	}
