948	/* Parse a file name into device and individual name. */
949	/* See gsfname.c for details. */
950	static int
951	parse_file_name(const ref * op, gs_parsed_file_name_t * pfn, bool safemode,
952	                gs_memory_t *memory)
953	{
954	    int code;
955	
956	    check_read_type(*op, t_string);
957	    code = gs_parse_file_name(pfn, (const char *)op->value.const_bytes,
958	                              r_size(op), memory);
959	    if (code < 0)
960	        return code;
961	    /*
962	     * Check here for the %pipe device which is illegal when
963	     * LockFilePermissions is true. In the future we might want to allow
964	     * the %pipe device to be included on the PermitFile... paths, but
965	     * for now it is simply disallowed.
966	     */
967	    if (pfn->iodev && safemode && strcmp(pfn->iodev->dname, "%pipe%") == 0)
968	        return gs_error_invalidfileaccess;
969	    return code;
970	}
