983	/* Parse the access string for opening a file. */
984	/* [4] is for r/w, +, b, \0. */
985	static int
986	parse_file_access_string(const ref *op, char file_access[4])
987	{
988	    const byte *astr;
989	
990	    check_read_type(*op, t_string);
991	    astr = op->value.const_bytes;
992	    switch (r_size(op)) {
993	        case 2:
994	            if (astr[1] != '+')
995	                return_error(gs_error_invalidfileaccess);
996	            file_access[1] = '+';
997	            file_access[2] = 0;
998	            break;
999	        case 1:
1000	            file_access[1] = 0;
1001	            break;
1002	        default:
1003	            return_error(gs_error_invalidfileaccess);
1004	    }
1005	    switch (astr[0]) {
1006	        case 'r':
1007	        case 'w':
1008	        case 'a':
1009	            break;
1010	        default:
1011	            return_error(gs_error_invalidfileaccess);
1012	    }
1013	    file_access[0] = astr[0];
1014	    return 0;
1015	}
