1019	/*
1020	 * Open a file specified by a parsed file name (which may be only a
1021	 * device).
1022	 */
1023	int
1024	zopen_file(i_ctx_t *i_ctx_p, const gs_parsed_file_name_t *pfn,
1025	           const char *file_access, stream **ps, gs_memory_t *mem)
1026	{
1027	    gx_io_device *const iodev = pfn->iodev;
1028	    int code = 0;
1029	
1030	    if (pfn->fname == NULL) {     /* just a device */
1031	        iodev->state = i_ctx_p;
1032	        code = iodev->procs.open_device(iodev, file_access, ps, mem);
1033	        iodev->state = NULL;
1034	        return code;
1035	    }
1036	    else {                      /* file */
1037	        iodev_proc_open_file((*open_file)) = iodev->procs.open_file;
1038	
1039	        if (open_file == 0)
1040	            open_file = iodev_os_open_file;
1041	        /* Check OS files to make sure we allow the type of access */
1042	        if (open_file == iodev_os_open_file) {
1043	            code = check_file_permissions(i_ctx_p, pfn->fname, pfn->len, pfn->iodev,
1044	                file_access[0] == 'r' ? "PermitFileReading" : "PermitFileWriting");
1045	
1046	            if (code < 0 && !file_is_tempfile(i_ctx_p,
1047	                                          (const uchar *)pfn->fname, pfn->len))
1048	                return code;
1049	        }
1050	        return open_file(iodev, pfn->fname, pfn->len, file_access, ps, mem);
1051	    }
1052	}
