1067	/* Make a t_file reference to a stream. */
1068	void
1069	make_stream_file(ref * pfile, stream * s, const char *access)
1070	{
1071	    uint attrs =
1072	        (access[1] == '+' ? a_write + a_read + a_execute : 0) |
1073	        imemory_space((gs_ref_memory_t *) s->memory);
1074	
1075	    if (access[0] == 'r') {
1076	        make_file(pfile, attrs | (a_read | a_execute), s->read_id, s);
1077	        s->write_id = 0;
1078	    } else {
1079	        make_file(pfile, attrs | a_write, s->write_id, s);
1080	        s->read_id = 0;
1081	    }
1082	}
