1084	/* return zero for success, -ve for error, +1 for continue */
1085	static int
1086	lib_file_open_search_with_no_combine(gs_file_path_ptr  lib_path, const gs_memory_t *mem, i_ctx_t *i_ctx_p,
1087	                                     const char *fname, uint flen, char *buffer, int blen, uint *pclen, ref *pfile,
1088	                                     gx_io_device *iodev, bool starting_arg_file, char *fmode)
1089	{
1090	    stream *s;
1091	    uint blen1 = blen;
1092	    struct stat fstat;
1093	    int code = 1;
1094	
1095	    if (gp_file_name_reduce(fname, flen, buffer, &blen1) != gp_combine_success)
1096	      goto skip;
1097	
1098	    if (starting_arg_file || check_file_permissions(i_ctx_p, buffer, blen1, iodev, "PermitFileReading") >= 0) {
1099	        if (iodev_os_open_file(iodev, (const char *)buffer, blen1,
1100	                       (const char *)fmode, &s, (gs_memory_t *)mem) == 0) {
1101	            *pclen = blen1;
1102	            make_stream_file(pfile, s, "r");
1103	            code = 0;
1104	        }
1105	    }
1106	    else {
1107	        /* If we are not allowed to open the file by check_file_permissions_aux()
1108	         * and if the file exists, throw an error.......
1109	         * Otherwise, keep searching.
1110	         */
1111	        if ((*iodev->procs.file_status)(iodev,  buffer, &fstat) >= 0) {
1112	            code = gs_note_error(gs_error_invalidfileaccess);
1113	        }
1114	    }
1115	
1116	 skip:
1117	    return code;
1118	}
