1120	/* return zero for success, -ve for error, +1 for continue */
1121	static int
1122	lib_file_open_search_with_combine(gs_file_path_ptr  lib_path, const gs_memory_t *mem, i_ctx_t *i_ctx_p,
1123	                                  const char *fname, uint flen, char *buffer, int blen, uint *pclen, ref *pfile,
1124	                                  gx_io_device *iodev, bool starting_arg_file, char *fmode)
1125	{
1126	    stream *s;
1127	    const gs_file_path *pfpath = lib_path;
1128	    uint pi;
1129	    int code = 1;
1130	
1131	    for (pi = 0; pi < r_size(&pfpath->list) && code == 1; ++pi) {
1132	        const ref *prdir = pfpath->list.value.refs + pi;
1133	        const char *pstr = (const char *)prdir->value.const_bytes;
1134	        uint plen = r_size(prdir), blen1 = blen;
1135	        gs_parsed_file_name_t pname;
1136	        gp_file_name_combine_result r;
1137	
1138	        /* We need to concatenate and parse the file name here
1139	         * if this path has a %device% prefix.              */
1140	        if (pstr[0] == '%') {
1141	            /* We concatenate directly since gp_file_name_combine_*
1142	             * rules are not correct for other devices such as %rom% */
1143	            code = gs_parse_file_name(&pname, pstr, plen, mem);
1144	            if (code < 0) {
1145	                code = 1;
1146	                continue;
1147	            }
1148	            if (blen < max(pname.len, plen) + flen)
1149	            	return_error(gs_error_limitcheck);
1150	            memcpy(buffer, pname.fname, pname.len);
1151	            memcpy(buffer+pname.len, fname, flen);
1152	            code = pname.iodev->procs.open_file(pname.iodev, buffer, pname.len + flen, fmode,
1153	                                          &s, (gs_memory_t *)mem);
1154	            if (code < 0) {
1155	                code = 1;
1156	                continue;
1157	            }
1158	            make_stream_file(pfile, s, "r");
1159	            /* fill in the buffer with the device concatenated */
1160	            memcpy(buffer, pstr, plen);
1161	            memcpy(buffer+plen, fname, flen);
1162	            *pclen = plen + flen;
1163	            code = 0;
1164	        } else {
1165	            r = gp_file_name_combine(pstr, plen,
1166	                    fname, flen, false, buffer, &blen1);
1167	            if (r != gp_combine_success)
1168	                continue;
1169	            if (starting_arg_file || check_file_permissions(i_ctx_p, buffer,
1170	                                      blen1, iodev, "PermitFileReading") >= 0) {
1171	
1172	                if (iodev_os_open_file(iodev, (const char *)buffer, blen1,
1173	                            (const char *)fmode, &s, (gs_memory_t *)mem) == 0) {
1174	                    *pclen = blen1;
1175	                    make_stream_file(pfile, s, "r");
1176	                    code = 0;
1177	                }
1178	            }
1179	            else {
1180	                struct stat fstat;
1181	                /* If we are not allowed to open the file by check_file_permissions_aux()
1182	                 * and if the file exists, throw an error.......
1183	                 * Otherwise, keep searching.
1184	                 */
1185	                if ((*iodev->procs.file_status)(iodev,  (const char *)buffer, &fstat) >= 0) {
1186	                    code = gs_note_error(gs_error_invalidfileaccess);
1187	                }
1188	            }
1189	        }
1190	    }
1191	    return code;
1192	}
1193	
1194	/* Return a file object of of the file searched for using the search paths. */
1195	/* The fname cannot contain a device part (%...%) but the lib paths might. */
1196	/* The startup code calls this to open the initialization file gs_init.ps. */
1197	/* The startup code also calls this to open @-files. */
1198	int
1199	lib_file_open(gs_file_path_ptr  lib_path, const gs_memory_t *mem, i_ctx_t *i_ctx_p,
1200	                       const char *fname, uint flen, char *buffer, int blen, uint *pclen, ref *pfile)
1201	{   /* i_ctx_p is NULL running arg (@) files.
1202	     * lib_path and mem are never NULL
1203	     */
1204	    bool starting_arg_file = (i_ctx_p == NULL) ? true : i_ctx_p->starting_arg_file;
1205	    bool search_with_no_combine = false;
1206	    bool search_with_combine = false;
1207	    char fmode[2] = { 'r', 0};
1208	    gx_io_device *iodev = iodev_default(mem);
1209	    gs_main_instance *minst = get_minst_from_memory(mem);
1210	    int code;
1211	
1212	    if (i_ctx_p && starting_arg_file)
1213	        i_ctx_p->starting_arg_file = false;
1214	
1215	    /* when starting arg files (@ files) iodev_default is not yet set */
1216	    if (iodev == 0)
1217	        iodev = (gx_io_device *)gx_io_device_table[0];
1218	
1219	    if (gp_file_name_is_absolute(fname, flen)) {
1220	       search_with_no_combine = true;
1221	       search_with_combine = false;
1222	    } else {
1223	       search_with_no_combine = starting_arg_file;
1224	       search_with_combine = true;
1225	    }
1226	    if (minst->search_here_first) {
1227	      if (search_with_no_combine) {
1228	        code = lib_file_open_search_with_no_combine(lib_path, mem, i_ctx_p,
1229	                                                    fname, flen, buffer, blen, pclen, pfile,
1230	                                                    iodev, starting_arg_file, fmode);
1231	        if (code <= 0) /* +ve means continue continue */
1232	          return code;
1233	      }
1234	      if (search_with_combine) {
1235	        code = lib_file_open_search_with_combine(lib_path, mem, i_ctx_p,
1236	                                                 fname, flen, buffer, blen, pclen, pfile,
1237	                                                 iodev, starting_arg_file, fmode);
1238	        if (code <= 0) /* +ve means continue searching */
1239	          return code;
1240	      }
1241	    } else {
1242	      if (search_with_combine) {
1243	        code = lib_file_open_search_with_combine(lib_path, mem, i_ctx_p,
1244	                                                 fname, flen, buffer, blen, pclen, pfile,
1245	                                                 iodev, starting_arg_file, fmode);
1246	        if (code <= 0) /* +ve means continue searching */
1247	          return code;
1248	      }
1249	      if (search_with_no_combine) {
1250	        code = lib_file_open_search_with_no_combine(lib_path, mem, i_ctx_p,
1251	                                                    fname, flen, buffer, blen, pclen, pfile,
1252	                                                    iodev, starting_arg_file, fmode);
1253	        if (code <= 0) /* +ve means continue searching */
1254	          return code;
1255	      }
1256	    }
1257	    return_error(gs_error_undefinedfilename);
1258	}
1259	
1260	/* The startup code calls this to open @-files. */
1261	gp_file *
1262	lib_fopen(const gs_file_path_ptr pfpath, const gs_memory_t *mem, const char *fname)
1263	{
1264	    /* We need a buffer to hold the expanded file name. */
1265	    char filename_found[DEFAULT_BUFFER_SIZE];
1266	    gp_file *file = NULL;
1267	    uint fnamelen;
1268	    ref obj;
1269	    int code;
1270	
1271	    /* open the usual 'stream', then if successful, return the file */
1272	    code = lib_file_open(pfpath, mem, NULL, fname, strlen(fname),
1273	                            filename_found, sizeof(filename_found), &fnamelen, &obj);
1274	
1275	    if (code < 0)
1276	        return NULL;
1277	    file = ((stream *)(obj.value.pfile))->file;
1278	    return file;
1279	}
1280	
1281	/* Open a file stream that reads a string. */
1282	/* (This is currently used only by the ccinit feature.) */
1283	/* The string must be allocated in non-garbage-collectable (foreign) space. */
1284	int
1285	file_read_string(const byte *str, uint len, ref *pfile, gs_ref_memory_t *imem)
1286	{
1287	    stream *s = file_alloc_stream((gs_memory_t *)imem, "file_read_string");
1288	
1289	    if (s == 0)
1290	        return_error(gs_error_VMerror);
1291	    sread_string(s, str, len);
1292	    s->foreign = 1;
1293	    s->write_id = 0;
1294	    make_file(pfile, a_readonly | imemory_space(imem), s->read_id, s);
1295	    s->save_close = s->procs.close;
1296	    s->procs.close = file_close_disable;
1297	    return 0;
1298	}
1299	
1300	/* Report an error by storing it in the stream's error_string. */
1301	int
1302	filter_report_error(stream_state * st, const char *str)
1303	{
1304	    if_debug1m('s', st->memory, "[s]stream error: %s\n", str);
1305	    strncpy(st->error_string, str, STREAM_MAX_ERROR_STRING);
1306	    /* Ensure null termination. */
1307	    st->error_string[STREAM_MAX_ERROR_STRING] = 0;
1308	    return 0;
1309	}
1310	
1311	/* Open a file stream for a filter. */
1312	int
1313	filter_open(const char *file_access, uint buffer_size, ref * pfile,
1314	            const stream_procs * procs, const stream_template * templat,
1315	            const stream_state * st, gs_memory_t *mem)
1316	{
1317	    stream *s;
1318	    uint ssize = gs_struct_type_size(templat->stype);
1319	    stream_state *sst = 0;
1320	    int code;
1321	
1322	    if (templat->stype != &st_stream_state) {
1323	        sst = s_alloc_state(mem, templat->stype, "filter_open(stream_state)");
1324	        if (sst == 0)
1325	            return_error(gs_error_VMerror);
1326	    }
1327	    code = file_open_stream((char *)0, 0, file_access, buffer_size, &s,
1328	                                (gx_io_device *)0, (iodev_proc_fopen_t)0, mem);
1329	    if (code < 0) {
1330	        gs_free_object(mem, sst, "filter_open(stream_state)");
1331	        return code;
1332	    }
1333	    s_std_init(s, s->cbuf, s->bsize, procs,
1334	               (*file_access == 'r' ? s_mode_read : s_mode_write));
1335	    s->procs.process = templat->process;
1336	    s->save_close = s->procs.close;
1337	    s->procs.close = file_close_file;
1338	    if (sst == 0) {
1339	        /* This stream doesn't have any state of its own. */
1340	        /* Hack: use the stream itself as the state. */
1341	        sst = (stream_state *) s;
1342	    } else if (st != 0)         /* might not have client parameters */
1343	        memcpy(sst, st, ssize);
1344	    s->state = sst;
1345	    s_init_state(sst, templat, mem);
1346	    sst->report_error = filter_report_error;
1347	
1348	    if (templat->init != 0) {
1349	        code = (*templat->init)(sst);
1350	        if (code < 0) {
1351	            gs_free_object(mem, sst, "filter_open(stream_state)");
1352	            gs_free_object(mem, s->cbuf, "filter_open(buffer)");
1353	            return code;
1354	        }
1355	    }
1356	    make_stream_file(pfile, s, file_access);
1357	    return 0;
1358	}
1359	
1360	/* Close a file object. */
1361	/* This is exported only for gsmain.c. */
1362	int
1363	file_close(ref * pfile)
1364	{
1365	    stream *s;
1366	
1367	    if (file_is_valid(s, pfile)) {      /* closing a closed file is a no-op */
1368	        if (sclose(s))
1369	            return_error(gs_error_ioerror);
1370	    }
1371	    return 0;
