31	/* Allocate and return a file stream. */
32	/* Return 0 if the allocation failed. */
33	/* The stream is initialized to an invalid state, so the caller need not */
34	/* worry about cleaning up if a later step in opening the stream fails. */
35	stream *
36	file_alloc_stream(gs_memory_t * mem, client_name_t cname)
37	{
38	    stream *s;
39	    s = s_alloc(mem, cname);
40	    if (s == 0)
41	        return 0;
42	    s_init_ids(s);
43	    s->is_temp = 0;		/* not a temp stream */
44	    s->foreign = 0;
45	    /*
46	     * Disable the stream now (in case we can't open the file,
47	     * or a filter init procedure fails) so that `restore' won't
48	     * crash when it tries to close open files.
49	     */
50	    s_disable(s);
51	    s->prev = 0;
52	    s->next = 0;
53	    return s;
54	}
55	
56	/* Open a file stream, optionally on an OS file. */
57	/* Return 0 if successful, error code if not. */
58	/* On a successful return, the C file name is in the stream buffer. */
59	/* If fname==0, set up the file entry, stream, and buffer, */
60	/* but don't open an OS file or initialize the stream. */
61	int
62	file_open_stream(const char *fname, uint len, const char *file_access,
63	                 uint buffer_size, stream ** ps, gx_io_device *iodev,
64	                 iodev_proc_fopen_t fopen_proc, gs_memory_t *mem)
65	{
66	    int code;
67	    gp_file *file;
68	    char fmode[4];  /* r/w/a, [+], [b], null */
69	
70	#ifdef DEBUG
71	    if (strlen(gp_fmode_binary_suffix) > 0) {
72	        if (strchr(file_access, gp_fmode_binary_suffix[0]) != NULL)
73		    dmprintf(mem, "\nWarning: spurious 'b' character in file access mode\n");
74		assert(strchr(file_access, gp_fmode_binary_suffix[0]) == NULL);
75	    }
76	#endif
77	
78	    if (!iodev)
79	        iodev = iodev_default(mem);
80	    code = file_prepare_stream(fname, len, file_access, buffer_size, ps, fmode, mem);
81	    if (code < 0)
82	        return code;
83	    if (fname == 0)
84	        return 0;
85	    if (fname[0] == 0)		/* fopen_proc gets NUL terminated string, not len */
86	        return 0;		/* so this is the same as len == 0, so return NULL */
87	    code = (*fopen_proc)(iodev, (char *)(*ps)->cbuf, fmode, &file,
88	                         (char *)(*ps)->cbuf, (*ps)->bsize, mem);
89	    if (code < 0) {
90	        /* discard the stuff we allocated to keep from accumulating stuff needing GC */
91	        gs_free_object(mem, (*ps)->cbuf, "file_close(buffer)");
92	        gs_free_object(mem, *ps, "file_prepare_stream(stream)");
93	        *ps = NULL;
94	        return code;
95	    }
96	    if (file_init_stream(*ps, file, fmode, (*ps)->cbuf, (*ps)->bsize) != 0)
97	        return_error(gs_error_ioerror);
98	    return 0;
99	}
100	
101	/* Close a file stream.  This replaces the close procedure in the stream */
102	/* for normal (OS) files and for filters. */
103	int
104	file_close_file(stream * s)
105	{
106	    stream *stemp = s->strm;
107	    gs_memory_t *mem;
108	    int code = file_close_disable(s);
109	
110	    if (code)
111	        return code;
112	    /*
113	     * Check for temporary streams created for filters.
114	     * There may be more than one in the case of a procedure-based filter,
115	     * or if we created an intermediate stream to ensure
116	     * a large enough buffer.  Note that these streams may have been
117	     * allocated by file_alloc_stream, so we mustn't free them.
118	     */
119	    while (stemp != 0 && stemp->is_temp != 0) {
120	        stream *snext = stemp->strm;
121	
122	        mem = stemp->memory;
123	        if (stemp->is_temp > 1)
124	            gs_free_object(mem, stemp->cbuf,
125	                           "file_close(temp stream buffer)");
126	        s_disable(stemp);
127	        stemp = snext;
128	    }
129	    mem = s->memory;
130	    gs_free_object(mem, s->cbuf, "file_close(buffer)");
131	    if (s->close_strm && stemp != 0)
132	        return sclose(stemp);
133	    return 0;
134	}
135	
136	/*
137	 * Set up a file stream on an OS file.  The caller has allocated the
138	 * stream and buffer.
139	 */
140	int
141	file_init_stream(stream *s, gp_file *file, const char *fmode, byte *buffer,
142	                 uint buffer_size)
143	{
144	    switch (fmode[0]) {
145	    case 'a':
146	        if (sappend_file(s, file, buffer, buffer_size) != 0)
147	            return ERRC;
148	        break;
149	    case 'r':
150	        /* Defeat buffering for terminals. */
151	        {
152	            int char_buffered = gp_file_is_char_buffered(file);
153	            if (char_buffered < 0)
154	                return char_buffered;
155	            sread_file(s, file, buffer, char_buffered ? 1 : buffer_size);
156	        }
157	        break;
158	    case 'w':
159	        swrite_file(s, file, buffer, buffer_size);
160	    }
161	    if (fmode[1] == '+')
162	        s->file_modes |= s_mode_read | s_mode_write;
163	    s->save_close = s->procs.close;
164	    s->procs.close = file_close_file;
165	    return 0;
166	}
167	
168	/* Prepare a stream with a file name. */
169	/* Return 0 if successful, error code if not. */
170	/* On a successful return, the C file name is in the stream buffer. */
171	/* If fname==0, set up stream, and buffer. */
172	int
173	file_prepare_stream(const char *fname, uint len, const char *file_access,
174	                 uint buffer_size, stream ** ps, char fmode[4], gs_memory_t *mem)
175	{
176	    byte *buffer;
177	    register stream *s;
178	
179	    /* Open the file, always in binary mode. */
180	    strcpy(fmode, file_access);
181	    strcat(fmode, gp_fmode_binary_suffix);
182	    if (buffer_size == 0)
183	        buffer_size = file_default_buffer_size;
184	    if (len >= buffer_size)    /* we copy the file name into the buffer */
185	        return_error(gs_error_limitcheck);
186	    /* Allocate the stream first, since it persists */
187	    /* even after the file has been closed. */
188	    s = file_alloc_stream(mem, "file_prepare_stream");
189	    if (s == 0)
190	        return_error(gs_error_VMerror);
191	    /* Allocate the buffer. */
192	    buffer = gs_alloc_bytes(mem, buffer_size, "file_prepare_stream(buffer)");
193	    if (buffer == 0) {
194	        gs_free_object(mem, s, "file_prepare_stream");
195	        return_error(gs_error_VMerror);
196	    }
197	    if (fname != 0) {
198	        memcpy(buffer, fname, len);
199	        buffer[len] = 0;	/* terminate string */
200	    } else
201	        buffer[0] = 0;	/* safety */
202	    s->cbuf = buffer;
203	    s->bsize = s->cbsize = buffer_size;
204	    s->save_close = 0;	    /* in case this stream gets disabled before init finishes */
205	    *ps = s;
206	    return 0;
207	}
